import React from 'react';
import { useApp } from '../context/AppContext';
import { getTheme } from '../utils/theme';

export default function Colleges() {
  const { setSelectedCollege, setPage, dark, resources, user, selectedCollege } = useApp();
  const css = getTheme(dark);

  // ✅ ONLY selected / user college
  const colleges =
    user?.role === 'student' && user?.college
      ? [user.college]
      : selectedCollege
      ? [selectedCollege]
      : [];

  return (
    <div className="fade-in">
      <div style={{ marginBottom: 28 }}>
        <h1 style={{ fontSize: 26, fontWeight: 800 }}>
          Your College
        </h1>
      </div>

      {colleges.length === 0 ? (
        <p>No college selected</p>
      ) : (
        colleges.map((c) => {
          const resCount = resources.filter(
            (r) => r.college === c._id || r.college?._id === c._id
          ).length;

          return (
            <div
              key={c._id}
              style={{
                ...css.card,
                marginBottom: 10,
                padding: 16,
              }}
            >
              <h3>{c.name}</h3>

              <p>{c.city}</p>

              <p>
                📚 {resCount} resources
              </p>
            </div>
          );
        })
      )}
    </div>
  );
}
